import { requireActiveSellerForUser } from '../../repositories/seller.repository.js';
import { getSellerDailyReportFacts, defaultReportDate, type SellerDailyReportFacts } from '../../repositories/insights.repository.js';
import { composeReplyWithFallback } from './llmProvider.js';

/**
 * A single thing the merchant can act on today. Actions are derived
 * arithmetically from the facts — never generated by a model — because an
 * invented action ("restock a product you don't sell") is worse than no
 * action at all. The LLM narrates; it never decides what to do.
 */
export interface RecommendedAction {
  kind: 'restock' | 'recover_carts' | 'fulfil_orders' | 'review_slow_movers' | 'investigate_drop' | 'investigate_conversion';
  title: string;
  detail: string;
  /** Severity ordering for the UI: 1 is most urgent. */
  priority: number;
}

export interface SellerDailyReport extends SellerDailyReportFacts {
  /** Prose summary. Deterministic when no real LLM is configured — see `composeReplyWithFallback`. */
  summary: string;
  actions: RecommendedAction[];
}

function formatMoney(minor: number, currency: string): string {
  return `${(minor / 100).toFixed(2)} ${currency}`;
}

function describeDelta(label: string, metric: { current: number; previous: number; deltaPct: number | null }, format: (n: number) => string): string {
  if (metric.deltaPct === null) {
    return metric.current === 0
      ? `${label}: none, same as the day before.`
      : `${label}: ${format(metric.current)}, up from none the day before.`;
  }
  const direction = metric.deltaPct >= 0 ? 'up' : 'down';
  return `${label}: ${format(metric.current)}, ${direction} ${Math.abs(metric.deltaPct)}% from ${format(metric.previous)}.`;
}

function buildActions(facts: SellerDailyReportFacts): RecommendedAction[] {
  const actions: RecommendedAction[] = [];

  for (const risk of facts.stockRisks.slice(0, 3)) {
    actions.push({
      kind: 'restock',
      title: `Restock ${risk.productName}`,
      detail: `${risk.available} left and selling ${risk.dailyVelocity}/day — about ${risk.daysOfCover} day${risk.daysOfCover === 1 ? '' : 's'} of cover (SKU ${risk.sku}).`,
      priority: 1
    });
  }

  if (facts.abandonedCarts.count > 0) {
    const names = facts.abandonedCarts.topProductNames;
    actions.push({
      kind: 'recover_carts',
      title: `Recover ${facts.abandonedCarts.count} abandoned cart${facts.abandonedCarts.count === 1 ? '' : 's'}`,
      detail: `${formatMoney(facts.abandonedCarts.valueMinor, facts.currency)} of indicative value sitting in carts from the last 7 days${names.length ? `, most often holding ${names.join(', ')}` : ''}.`,
      priority: 2
    });
  }

  if (facts.pendingFulfillmentCount > 0) {
    actions.push({
      kind: 'fulfil_orders',
      title: `Ship ${facts.pendingFulfillmentCount} waiting order${facts.pendingFulfillmentCount === 1 ? '' : 's'}`,
      detail: 'These orders are paid or confirmed and still unfulfilled.',
      priority: 2
    });
  }

  // A fall of more than a fifth day-over-day is worth a look; smaller swings are noise at this volume.
  if (facts.revenueMinor.deltaPct !== null && facts.revenueMinor.deltaPct <= -20) {
    actions.push({
      kind: 'investigate_drop',
      title: `Revenue fell ${Math.abs(facts.revenueMinor.deltaPct)}% day over day`,
      detail: `${formatMoney(facts.revenueMinor.current, facts.currency)} against ${formatMoney(facts.revenueMinor.previous, facts.currency)} on ${facts.comparedTo}.`,
      priority: 1
    });
  }

  // Only when both days were actually measured — a conversion rate that appeared
  // because tracking was switched on yesterday is not a drop.
  const conversion = facts.funnel.conversionRatePct;
  const priorConversion = facts.previousFunnel.conversionRatePct;
  if (conversion !== null && priorConversion !== null && priorConversion > 0 && conversion < priorConversion) {
    const dropPct = Math.round(((priorConversion - conversion) / priorConversion) * 1000) / 10;
    if (dropPct >= 20) {
      actions.push({
        kind: 'investigate_conversion',
        title: `Conversion fell from ${priorConversion}% to ${conversion}%`,
        detail: `${facts.funnel.sessions} session${facts.funnel.sessions === 1 ? '' : 's'}, ${facts.funnel.addToCarts} add${facts.funnel.addToCarts === 1 ? '' : 's'} to cart, ${facts.funnel.ordersPlaced} order${facts.funnel.ordersPlaced === 1 ? '' : 's'}${facts.funnel.cartAbandonmentRatePct !== null ? `, ${facts.funnel.cartAbandonmentRatePct}% of carts abandoned` : ''}.`,
        priority: 1
      });
    }
  }

  if (facts.slowMovers.length > 0) {
    const worst = facts.slowMovers[0]!;
    actions.push({
      kind: 'review_slow_movers',
      title: `${facts.slowMovers.length} product${facts.slowMovers.length === 1 ? '' : 's'} have not sold in 30 days`,
      detail: `Most stock tied up in ${worst.productName} (${worst.available} units, SKU ${worst.sku}).`,
      priority: 3
    });
  }

  return actions.sort((a, b) => a.priority - b.priority);
}

function buildFallbackSummary(facts: SellerDailyReportFacts): string {
  if (facts.orderCount.current === 0 && facts.orderCount.previous === 0) {
    // Traffic without orders is the more useful half of this sentence when it exists.
    return facts.funnel.sessions > 0
      ? `No orders on ${facts.date} or ${facts.comparedTo}, despite ${facts.funnel.sessions} session${facts.funnel.sessions === 1 ? '' : 's'} and ${facts.funnel.productViews} product view${facts.funnel.productViews === 1 ? '' : 's'}.`
      : `No orders on ${facts.date} or ${facts.comparedTo}.`;
  }

  const parts = [
    describeDelta('Revenue', facts.revenueMinor, (n) => formatMoney(n, facts.currency)),
    describeDelta('Orders', facts.orderCount, (n) => String(n))
  ];

  if (facts.topProducts.length > 0) {
    const top = facts.topProducts[0]!;
    parts.push(`Best seller: ${top.name} (${top.unitsSold} unit${top.unitsSold === 1 ? '' : 's'}, ${formatMoney(top.revenueMinor, facts.currency)}).`);
  }
  if (facts.funnel.conversionRatePct !== null) {
    parts.push(`Conversion: ${facts.funnel.conversionRatePct}% of ${facts.funnel.sessions} session${facts.funnel.sessions === 1 ? '' : 's'}.`);
  }
  if (facts.stockRisks.length > 0) {
    parts.push(`${facts.stockRisks.length} product${facts.stockRisks.length === 1 ? '' : 's'} may run out within ${facts.stockRisks[0]!.daysOfCover} day${facts.stockRisks[0]!.daysOfCover === 1 ? '' : 's'}.`);
  }
  return parts.join(' ');
}

/**
 * The merchant-facing daily report. Metrics and actions are computed from
 * MongoDB first; the model is handed that finished object and asked only to
 * narrate it, so the report degrades to a deterministic summary rather than
 * breaking when no provider is configured or one times out.
 */
export async function getSellerDailyReport(userId: string, date?: string): Promise<SellerDailyReport> {
  const seller = await requireActiveSellerForUser(userId);
  const reportDate = date ?? defaultReportDate();
  const facts = await getSellerDailyReportFacts(seller._id.toString(), reportDate);

  const actions = buildActions(facts);
  const fallbackReply = buildFallbackSummary(facts);

  const summary = await composeReplyWithFallback({
    purpose: 'daily-report',
    userMessage: `Summarise how my store did on ${facts.date} compared with ${facts.comparedTo}.`,
    context: {
      storeName: seller.storeName,
      date: facts.date,
      comparedTo: facts.comparedTo,
      currency: facts.currency,
      revenue: { ...facts.revenueMinor, formatted: formatMoney(facts.revenueMinor.current, facts.currency) },
      orders: facts.orderCount,
      unitsSold: facts.unitsSold,
      averageOrderValue: { ...facts.averageOrderValueMinor, formatted: formatMoney(facts.averageOrderValueMinor.current, facts.currency) },
      topProducts: facts.topProducts.map((p) => `${p.name}: ${p.unitsSold} units, ${formatMoney(p.revenueMinor, facts.currency)}`),
      stockRisks: facts.stockRisks.map((r) => `${r.productName}: ${r.available} left, ${r.dailyVelocity}/day, ~${r.daysOfCover} days of cover`),
      slowMovers: facts.slowMovers.map((s) => `${s.productName}: ${s.available} unsold units`),
      abandonedCarts: facts.abandonedCarts,
      pendingFulfillmentCount: facts.pendingFulfillmentCount,
      // Null means not measured. The system prompt forbids inventing figures, so a null
      // conversion rate must stay absent from the prose rather than becoming "0%".
      storefrontFunnel:
        facts.funnel.conversionRatePct === null
          ? 'not measured on this day — the storefront sent no analytics events'
          : {
              sessions: facts.funnel.sessions,
              productViews: facts.funnel.productViews,
              addToCarts: facts.funnel.addToCarts,
              ordersPlaced: facts.funnel.ordersPlaced,
              conversionRatePct: facts.funnel.conversionRatePct,
              previousConversionRatePct: facts.previousFunnel.conversionRatePct,
              cartAbandonmentRatePct: facts.funnel.cartAbandonmentRatePct
            },
      recommendedActions: actions.map((a) => a.title),
      fallbackReply
    }
  });

  return { ...facts, summary, actions };
}
